// TH18 v1.00a Extra / stage07
// source: st07bs.ecl.txt::Boss6:579-640, dependency Boss6_at:642-667
// Extra nonspell: source enemy starts at (0,128) (task hand-off), static ABS, REL=0.
// Source timerReset + setInterrupt(slot0, 3200, 4200, "BossCard6"): this unit's
// activity ends at source frame 4200; the next card is not executed here.

const TIME_LIMIT: int = 4380;      // 120 opening buffer + 4200 source slot + 60 tail
const OPENING_BUFFER: int = 120;

// etSprite(12, 14): TH18 type 12 arrowhead, color 14.
const TH18_ARROWHEAD: int = 544;

// ---- Boss6_at(642-667) parameters -> target ----
// etAim(5): fixed half-step-offset ring  -> sh_ring(1), sh_aim(0).
//   angle = alpha + pi/N + i*2pi/N + q*delta
// etCount(5,6): 5 paths x 6 layers.
// etAngle(alpha, delta): delta = +/-6deg; alpha starts at %ANGLE_PLAYER and
//   advances by +/-9deg after every volley.
// etSpeed(1.2, 0.0): layer speed v(q) = 1.2 - 0.24*q.
// etOffset(0,-24), etDist(32): spawn point = enemy + (0,-24) + (32-4*v) along
//   the bullet angle; the 4*v is the retained ANIM(a=1) birth backwards shift.
// Two async calls become one task: both fire on the same frame and neither is
// cancelled inside this unit, so a single loop keeps both phases and order.
const HALF_STEP: int = 6554;        // pi/5 rad in BAM, nearest
const BASE_SPIN: int = 1638;        // 0.15707964 rad, +9deg
const LAYER_SPREAD: int = 1092;     // 0.10471976 rad, 6deg

// moveRand(60, 4, 1.0) direction bands for moveLimit(0,128,240,64):
// limit box x in [-120,120], y in [96,160]; direction inner zone x +/-60,
// y 112..144. Copied from the verified movement recipe with this box.
const MOVE_START: int = 280;        // first moveRand: boss frame 180 + wait(100)
const MOVE_PERIOD: int = 160;       // wait(60) + wait(100)
const MOVE_STEPS: int = 60;

// 0x2 ANIM (visual) + 0x200000 VELTIME(a=60, r=3.0, s=current angle)
// + 0x8 ANGLE_ACCEL(a=30, r=-0.03, s=0). EX entries are async=0, so the
// effects run in sequence: speed ramps to 3.0 over 60 frames, then
// 3.0 - 0.03*30 = 2.1 over the next 30 frames, with no turning.
xformdef BOSS6_BULLET {
    step_speed(3fx, 60);
    wait(60);
    step_speed(2.1fx, 30);
}

// ---------------------------------------------------------------------------
// movement helper (TH18 compile of 412 moveRand: speed 1-k/60, mode0).
// Target integrates in phase 5 after ECL, so the next source movement tick is
// armed one frame ahead; emit still reads the current position.
// ---------------------------------------------------------------------------
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < MOVE_STEPS { speed = (MOVE_STEPS - k) as fx / MOVE_STEPS; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

// 412 moveRand: one direction sample per call, not per frame.
sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

// Boss6 main loop bookkeeping: moveRand starts at boss frame 280 and repeats
// every 160 frames; each call lasts 60 movement ticks.
sub move_step(t: int) {
    if t >= MOVE_START {
        var p: int = (t - MOVE_START) % MOVE_PERIOD;
        if p == 0 { card_move_rand(); }
        else if p < MOVE_STEPS { card_arm_next_step(); }
    }
}

// One emitter's volley, preserving source layer-outer/path-inner creation order.
// sh_count(5,1) gives base + (i*65536)/5; per-layer delta is folded into base.
sub volley_slot(slot: int, base: int, step: int) {
    for q in 0..6 {
        var speed: fx = 1.2fx - (q as fx) * 0.24fx;
        sh_angle(slot, (base + HALF_STEP + q * step) as angle, 0deg);
        sh_speed(slot, speed, 0fx);
        sh_dist(slot, 32fx - 4fx * speed);
        sh_fire(slot);
    }
}

// ---------------------------------------------------------------------------
// Real source enemy: Boss6 setup, first shot wait, attack + moveRand loop.
// ---------------------------------------------------------------------------
async sub boss_main() {
    set_invuln(65535);                 // training shell: source setInvuln(120)
    set_hurtbox(20fx);                 // source 500 setHurtbox(40,40) -> 40/2
    set_hitbox(24fx);                  // source 501 setHitbox(48,48) -> 48/2
    set_enemy_flag(ENEMY_NO_BODY, 0);  // source flagClear(3) clears 0x2

    // 600/607/602: etNew + etAim(5) + etSprite(12,14)
    sh_reset(0);
    sh_sprite(0, TH18_ARROWHEAD, 14);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 5, 1);
    sh_offset(0, 0fx, -24fx);          // 603 etOffset(0,-24)
    sh_xform(0, BOSS6_BULLET);
    sh_reset(1);
    sh_sprite(1, TH18_ARROWHEAD, 14);
    sh_ring(1, 1);
    sh_aim(1, 0);
    sh_count(1, 5, 1);
    sh_offset(1, 0fx, -24fx);
    sh_xform(1, BOSS6_BULLET);

    // 619 movePosTime(60,4,0,128) from the given (0,128) start is zero motion;
    // 620 wait(120), then 621 moveLimit (modelled per tick by the helper),
    // 622-624 anmPlay/playSound + wait(60) -> first etOn at source frame 180.
    wait(120);
    wait(60);

    // Boss6_at entry: %G = %ANGLE_PLAYER, H = 10000, first etOn immediately.
    var g0: int = aim_player() as int;
    var g1: int = g0;
    var t: int = 180;
    for v in 0..403 {                  // volleys at source 180..4200, every 10
        volley_slot(0, g0, -LAYER_SPREAD);
        volley_slot(1, g1, LAYER_SPREAD);
        g0 = g0 + BASE_SPIN;
        g1 = g1 - BASE_SPIN;
        if v < 402 {
            for k in 0..10 {
                wait(1);
                t = t + 1;
                move_step(t);
            }
        }
    }
    // The source slot0 timeout at 4200 hands over to BossCard6; keep the boss
    // present for the remaining tail frames without adding volleys.
    wait(60);
}

// ---------------------------------------------------------------------------
// Training shell: control at (0,0) owns the phase; real enemy is spawned at
// the source hand-off point (0,128) after the opening buffer.
// ---------------------------------------------------------------------------
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 18200, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
